CC: stable@vger.kernel.org
Signed-off-by: Conor Dooley <conor.dooley@microchip.com>
Link: https://patch.msgid.link/20260430-hamstring-busload-f941d0347b5e@spud
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The QSPI hardware automatically controls the built-in chip select (CS), asserting it when data is written to the transmit buffer and deasserting it after the programmed number of bytes are sent. When multiple devices are attached and additional devices use GPIO CS, the built-in CS is inadvertently asserted during transfers intended only for the GPIO‑controlled device, causing interference and incorrect operation. The driver did not disable this automatic behavior and did not manually control the built‑in CS, leading to conflicts.

Here is the patch:
 #define STATUS_MASK		GENMASK(8, 0)

+/*
+ * QSPI Direct Access register defines
+ */
+#define DIRECT_ACCESS_EN_SSEL		BIT(0)
+#define DIRECT_ACCESS_OP_SSEL		BIT(1)
+#define DIRECT_ACCESS_OP_SSEL_SHIFT	1
+
 #define BYTESUPPER_MASK		GENMASK(31, 16)
 #define BYTESLOWER_MASK		GENMASK(15, 0)

+static void mchp_coreqspi_set_cs(struct spi_device *spi, bool enable)
+{
+	struct mchp_coreqspi *qspi = spi_controller_get_devdata(spi->controller);
+	u32 val;
+
+	val = readl(qspi->regs + REG_DIRECT_ACCESS);
+
+	val &= ~DIRECT_ACCESS_OP_SSEL;
+	val |= !enable << DIRECT_ACCESS_OP_SSEL_SHIFT;
+
+	writel(val, qspi->regs + REG_DIRECT_ACCESS);
+}
+
+static int mchp_coreqspi_setup(struct spi_device *spi)
+{
+	struct mchp_coreqspi *qspi = spi_controller_get_devdata(spi->controller);
+	u32 val;
+
+	/*
+	 * Active low devices need to be specifically set to their inactive
+	 * states during probe.
+	 */
+	if (spi->mode & SPI_CS_HIGH)
+		return 0;
+
+	val = readl(qspi->regs + REG_DIRECT_ACCESS);
+	val |= DIRECT_ACCESS_OP_SSEL;
+	writel(val, qspi->regs + REG_DIRECT_ACCESS);
+
+	return 0;
+}
+
 static inline void mchp_coreqspi_read_op(struct mchp_coreqspi *qspi)
 {
 	u32 control, data;

 	if (!qspi->rx_len)
 		return;

 	control = readl_relaxed(qspi->regs + REG_CONTROL);

 	/*
 	 * Read 4-bytes from the SPI FIFO in single transaction and then read
 	 * the reamaining data byte wise.
 	 */
 	control |= CONTROL_FLAGSX4;
 	writel_relaxed(control, qspi->regs + REG_CONTROL);

 	while (qspi->rx_len >= 4) {
 		while (readl_relaxed(qspi->regs + REG_STATUS) & STATUS_RXFIFOEMPTY)
 			;
 		data = readl_relaxed(qspi->regs + REG_X4_RX_DATA);
 		*(u32 *)qspi->rxbuf = data;
 		qspi->rxbuf += 4;
 		qspi->rx_len -= 4;
 	}

 	control &= ~CONTROL_FLAGSX4;
 	writel_relaxed(control, qspi->regs + REG_CONTROL);

 	while (qspi->rx_len--) {
 		while (readl_relaxed(qspi->regs + REG_STATUS) & STATUS_RXFIFOEMPTY)
 			;
 		data = readl_relaxed(qspi->regs + REG_RX_DATA);
 		*qspi->rxbuf++ = (data & 0xFF);
 	}
 }


-static int mchp_coreqspi_setup_op(struct spi_device *spi_dev)
-{
-	struct spi_controller *ctlr = spi_dev->controller;
-	struct mchp_coreqspi *qspi = spi_controller_get_devdata(ctlr);
-	u32 control = readl_relaxed(qspi->regs + REG_CONTROL);
-
-	control |= (CONTROL_MASTER | CONTROL_ENABLE);
-	control &= ~CONTROL_CLKIDLE;
-	writel_relaxed(control, qspi->regs + REG_CONTROL);
-
-	return 0;
-}
-
 static inline void mchp_coreqspi_config_op(struct mchp_coreqspi *qspi, const struct spi_mem_op *op)
 {
 	u32 idle_cycles = 0;
 	int total_bytes, cmd_bytes, frames, ctrl;

 	cmd_bytes = op->cmd.nbytes + op->addr.nbytes;
 	total_bytes = cmd_bytes + op->data.nbytes;

 	/*
 	 * As per the coreQSPI IP spec,the number of command and data bytes are
 	 * controlled by the frames register for each SPI sequence. This supports
 	 * the SPI flash memory read and writes sequences as below. so configure
 	 * the cmd and total bytes accordingly.
 	 * ---------------------------------------------------------------------
 	 * TOTAL BYTES  |  CMD BYTES | What happens                             |
 	 * ______________________________________________________________________
 	 *              |            |                                          |
 	 *     1        |   1        | The SPI core will transmit a single byte |
 	 *              |            | and receive data is discarded            |
 	 *              |            |                                          |
 	 *     1        |   0        | The SPI core will transmit a single byte |
 	 *              |            | and return a single byte                 |
 	 *              |            |                                          |
 	 *     10       |   4        | The SPI core will transmit 4 command     |
 	 *              |            | bytes discarding the receive data and    |
 	 *              |            | transmits 6 dummy bytes returning the 6  |
 	 *              |            | received bytes and return a single byte  |
 	 *              |            |                                          |
 	 *     10       |   10       | The SPI core will transmit 10 command    |
 	 *              |            |                                          |
 	 *     10       |    0       | The SPI core will transmit 10 command    |
 	 *              |            | bytes and returning 10 received bytes    |
 	 * ______________________________________________________________________
 	 */
 	if (!(op->data.dir == SPI_MEM_DATA_IN))
 		cmd_bytes = total_bytes;

 	frames = total_bytes & BYTESUPPER_MASK;
 	writel_relaxed(frames, qspi->regs + REG_FRAMESUP);
 	frames = total_bytes & BYTESLOWER_MASK;
 	frames |= cmd_bytes << FRAMES_CMDBYTES_SHIFT;

 	if (op->dummy.buswidth)
 		idle_cycles = op->dummy.nbytes * 8 / op->dummy.buswidth;

 	frames |= idle_cycles << FRAMES_IDLE_SHIFT;
 	ctrl = readl_relaxed(qspi->regs + REG_CONTROL);

 	if (ctrl & CONTROL_MODE12_MASK)
 		frames |= (1 << FRAMES_SHIFT);

 	frames |= FRAMES_FLAGWORD;
 	writel_relaxed(frames, qspi->regs + REG_FRAMES);
 }


 static int mchp_coreqspi_exec_op(struct spi_mem *mem, const struct spi_mem_op *op)
 {
 	struct mchp_coreqspi *qspi = spi_controller_get_devdata
 				    (mem->spi->controller);
 	u32 address = op->addr.val;
 	u8 opcode = op->cmd.opcode;
 	u8 opaddr[5];
 	int err, i;

 	mutex_lock(&qspi->op_lock);
 	err = mchp_coreqspi_wait_for_ready(qspi);
 	if (err) {
 		dev_err(&mem->spi->dev, "Timeout waiting on QSPI ready.\n");
 		goto error;
 	}

 	err = mchp_coreqspi_setup_clock(qspi, mem->spi, op->max_freq);
 	if (err)
 		goto error;

 	err = mchp_coreqspi_set_mode(qspi, op);
 	if (err)
 		goto error;

 	reinit_completion(&qspi->data_completion);
 	mchp_coreqspi_config_op(qspi, op);
+	mchp_coreqspi_set_cs(mem->spi, true);
 	if (op->cmd.opcode) {
 		qspi->txbuf = &opcode;
 		qspi->rxbuf = NULL;
 		qspi->tx_len = op->cmd.nbytes;
 		qspi->rx_len = 0;
 		mchp_coreqspi_write_op(qspi);
 	}

 	qspi->txbuf = &opaddr[0];
 	if (op->addr.nbytes) {
 		for (i = 0; i < op->addr.nbytes; i++)
 			qspi->txbuf[i] = address >> (8 * (op->addr.nbytes - i - 1));

 		qspi->rxbuf = NULL;
 		qspi->tx_len = op->addr.nbytes;
 		qspi->rx_len = 0;
 		mchp_coreqspi_write_op(qspi);
 	}

 	if (op->data.nbytes) {
 		if (op->data.dir == SPI_MEM_DATA_OUT) {
 			qspi->txbuf = (u8 *)op->data.buf.out;
 			qspi->rxbuf = NULL;
 			qspi->rx_len = 0;
 			qspi->tx_len = op->data.nbytes;
 			mchp_coreqspi_write_op(qspi);
 		} else {
 			qspi->txbuf = NULL;
 			qspi->rxbuf = (u8 *)op->data.buf.in;
 			qspi->rx_len = op->data.nbytes;
 			qspi->tx_len = 0;
 		}
 	}

 	mchp_coreqspi_enable_ints(qspi);

 	if (!wait_for_completion_timeout(&qspi->data_completion, msecs_to_jiffies(1000)))
 		err = -ETIMEDOUT;

 error:
+	mchp_coreqspi_set_cs(mem->spi, false);
 	mutex_unlock(&qspi->op_lock);
 	mchp_coreqspi_disable_ints(qspi);

 	return err;
 }


 static int mchp_coreqspi_probe(struct platform_device *pdev)
 {
 	struct spi_controller *ctlr;
 	struct mchp_coreqspi *qspi;
 	struct device *dev = &pdev->dev;
 	struct device_node *np = dev->of_node;
 	int ret;
+	u32 num_cs, val;

 	ctlr = devm_spi_alloc_host(&pdev->dev, sizeof(*qspi));
 	if (!ctlr)
 		return -ENOMEM;

 	qspi = spi_controller_get_devdata(ctlr);
 	platform_set_drvdata(pdev, ctlr);

 	qspi->regs = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(qspi->regs))
 		return dev_err_probe(&pdev->dev, PTR_ERR(qspi->regs),
 				     "failed to map registers\n");

 	qspi->clk = devm_clk_get_enabled(&pdev->dev, NULL);
 	if (IS_ERR(qspi->clk))
 		return dev_err_probe(&pdev->dev, PTR_ERR(qspi->clk),
 				     "could not get clock\n");

 	init_completion(&qspi->data_completion);
 	mutex_init(&qspi->op_lock);

 	qspi->irq = platform_get_irq(pdev, 0);
 	if (qspi->irq < 0)
 		return qspi->irq;

 	ret = devm_request_irq(&pdev->dev, qspi->irq, mchp_coreqspi_isr,
 			       IRQF_SHARED, pdev->name, qspi);
 	if (ret) {
 		dev_err(&pdev->dev, "request_irq failed %d\n", ret);
 		return ret;
 	}

+	/*
+	 * The IP core only has a single CS, any more have to be provided via
+	 * gpios
+	 */
+	if (of_property_read_u32(pdev->dev.of_node, "num-cs", &num_cs))
+		num_cs = 1;
+
+	ctlr->num_chipselect = num_cs;
+
 	ctlr->bits_per_word_mask = SPI_BPW_MASK(8);
 	ctlr->mem_ops = &mchp_coreqspi_mem_ops;
 	ctlr->mem_caps = &mchp_coreqspi_mem_caps;
-	ctlr->setup = mchp_coreqspi_setup_op;
 	ctlr->mode_bits = SPI_CPOL | SPI_CPHA | SPI_RX_DUAL | SPI_RX_QUAD |
 			  SPI_TX_DUAL | SPI_TX_QUAD;
 	ctlr->dev.of_node = np;
 	ctlr->min_speed_hz = clk_get_rate(qspi->clk) / 30;
 	ctlr->prepare_message = mchp_coreqspi_prepare_message;
 	ctlr->unprepare_message = mchp_coreqspi_unprepare_message;
 	ctlr->transfer_one = mchp_coreqspi_transfer_one;
-	ctlr->num_chipselect = 2;
+	ctlr->setup = mchp_coreqspi_setup;
+	ctlr->set_cs = mchp_coreqspi_set_cs;
 	ctlr->use_gpio_descriptors = true;

+	val = readl_relaxed(qspi->regs + REG_CONTROL);
+	val |= (CONTROL_MASTER | CONTROL_ENABLE);
+	writel_relaxed(val, qspi->regs + REG_CONTROL);
+
+	/*
+	 * Put cs into software controlled mode
+	 */
+	val = readl_relaxed(qspi->regs + REG_DIRECT_ACCESS);
+	val |= DIRECT_ACCESS_EN_SSEL;
+	writel(val, qspi->regs + REG_DIRECT_ACCESS);
+
 	ret = spi_register_controller(ctlr);
 	if (ret)
 		return dev_err_probe(&pdev->dev, ret,
 				     "spi_register_controller failed\n");

 	return 0;
 }



